      if (!secureTokenOk(request, this.env)) return Response.json({ ok: false, error: "UNAUTHORIZED" }, { status: 401 });
      const body = await request.json().catch(() => null), rows = Array.isArray(body?.rows) ? body.rows : [];
      if (!rows.length || rows.length > 1e4) return Response.json({ ok: false, error: "INVALID_IMPORT_ROWS" }, { status: 400 });
      const r = await this.upsertLedgerRows(rows);
      return Response.json({ ok: true, version: STAT_LEDGER_VERSION, inserted: r.inserted, updated: r.updated, unchanged: r.unchanged, ledgerTotal: r.meta.ledgerTotal, settledTotal: r.meta.settledTotal, pending: r.meta.pending });
    }
    if (u.pathname === "/ledger-sync" && request.method === "POST") {
      if (!secureTokenOk(request, this.env)) return Response.json({ ok: false, error: "UNAUTHORIZED" }, { status: 401 });
      const r = await this.syncStatisticsLedger();
      return Response.json({ ok: true, version: STAT_LEDGER_VERSION, inserted: r.inserted, updated: r.updated, ledgerTotal: r.meta.ledgerTotal, settledTotal: r.meta.settledTotal, pending: r.meta.pending });
    }
    if (u.pathname === "/ledger-health" && request.method === "GET") {
      const m = normalizeLedgerMeta(await this.ctx.storage.get(STAT_LEDGER_META_KEY));
      return Response.json({ ok: true, version: STAT_LEDGER_VERSION, retention: "LONG_TERM_NO_APPLICATION_EXPIRY", ...m, duplicateReconciliation: await this.__b46RepairStatus() });
    }
    if (u.pathname === "/statistics" && request.method === "GET") {
      const cursor = u.searchParams.get("cursor");
      if (cursor !== null && (!cursor.startsWith(STAT_LEDGER_PREFIX) || cursor.length > 1024))
        return Response.json({ ok: false, error: "INVALID_STATISTICS_CURSOR" }, { status: 400 });
      if (!cursor) {
        await this.scanIfDue();
        await this.syncStatisticsLedger();
      }
      return Response.json(await this.statisticsLedgerResponse(cursor, u.searchParams.get("paged") === "1" || cursor !== null));
    }
    return super.fetch(request);
  }

async fetch(request, env) {
    if (request.method === "OPTIONS") return cors(request, new Response(null, { status: 204 }));
    const u = new URL(request.url), allowed = ["/health", "/registry", "/settings", "/scan", "/board", "/signals", "/statistics", "/history", "/fixture-odds", "/referee", "/reconcile-final", "/bridge-health", "/ledger-import", "/ledger-sync", "/ledger-health"];
    if (!allowed.includes(u.pathname)) return cors(request, new Response("Not found", { status: 404 }));
    return cors(request, await stub(env).fetch(new Request(`https://engine.internal${u.pathname}${u.search}`, request)));
  }

function routeOf(pathname) {
  const p = String(pathname || "");
  if (p === "/health" || p.endsWith("/health")) return "/health";
  if (p === "/settings" || p.endsWith("/settings")) return "/settings";
  if (p === "/fixture-odds" || p.endsWith("/fixture-odds")) return "/fixture-odds";
  if (p === "/board-cache" || p.endsWith("/board-cache")) return "/board-cache";
  if (p === "/prewarm" || p.endsWith("/prewarm")) return "/prewarm";
  return p;
}

async cacheSnapshot(fixtureIds) {
    const ids = safeFixtureIds(fixtureIds);
    const cfg = await this.config();
    const entries = {};
    let staleHits = 0;
    for (const fixtureId of ids) {
      const hit = await this.cached(fixtureId);
      if (!hit) continue;
      const ageMs = Math.max(0, now() - Number(hit.fetchedAt || 0));
      const stale = ageMs >= cfg.cacheMs;
      if (stale) staleHits += 1;
      entries[fixtureId] = {
        fullOdds: hit.fullOdds,
        fetchedAt: Number(hit.fetchedAt || 0),
        ageMs,
        stale,
        bookmakerCount: Array.isArray(hit?.fullOdds?.bookmakers) ? hit.fullOdds.bookmakers.length : 0
      };
    }
    return {
      ok: true,
      version: VERSION,
      mode: "CENTRAL_CACHE_READ_ONLY",
      fixtureCount: ids.length,
      hits: Object.keys(entries).length,
      staleHits,
      externalRequestsAdded: 0,
      entries
    };
  }

async fetch(request) {
    const url = new URL(request.url);
    const route = routeOf(url.pathname);
    if (route === "/health" && request.method === "GET") return response(await this.health());
    if (route === "/settings") {
      if (request.method === "GET") return response({ ok: true, version: VERSION, config: await this.config(), presets: Object.values(PRESETS) });
      if (request.method === "PUT" || request.method === "POST") {
        try {
          const body = await request.json().catch(() => ({}));
          const cfg = await this.setConfig(body?.mode);
          return response({ ok: true, version: VERSION, config: cfg, presets: Object.values(PRESETS) });
        } catch (err) {
          return response({ ok: false, version: VERSION, error: String(err?.message || err) }, Number(err?.status || 400));
        }
      }
      return response({ ok: false, version: VERSION, error: "METHOD_NOT_ALLOWED" }, 405);
    }
    if (route === "/board-cache") {
      if (request.method !== "POST") return response({ ok: false, version: VERSION, error: "METHOD_NOT_ALLOWED" }, 405);
      const body = await request.json().catch(() => ({}));
      return response(await this.cacheSnapshot(body?.fixtureIds));
    }
    if (route === "/prewarm") {
      if (request.method !== "POST") return response({ ok: false, version: VERSION, error: "METHOD_NOT_ALLOWED" }, 405);
      const body = await request.json().catch(() => ({}));
      return response(await this.prewarm(body?.fixtureIds));
    }
    if (route !== "/fixture-odds") return response({ ok: false, version: VERSION, error: "NOT_FOUND", path: url.pathname }, 404);
    if (request.method !== "GET") return response({ ok: false, version: VERSION, error: "METHOD_NOT_ALLOWED" }, 405);
    const fixtureId = safeFixtureId(url.searchParams.get("fixtureId") || url.searchParams.get("fixture_id") || url.searchParams.get("id"));
    if (!fixtureId) return response({ ok: false, version: VERSION, error: "INVALID_FIXTURE_ID" }, 400);
    try {
      const body = await this.loadDeduped(fixtureId);
      return response(body, 200, { "x-nomad-full-market-cache": body.cached ? body.stale ? "STALE" : "HIT" : "MISS" });
    } catch (err) {
      const status = Number(err?.status || 502), retryAfter = finite(err?.retryAfter);
      return response({ ok: false, version: VERSION, fixtureId, error: String(err?.message || err), retryAfterSec: retryAfter, guard: err?.guard || null }, status, retryAfter ? { "retry-after": String(retryAfter) } : {});
    }
  }

async fetch(request, env) {
    const route = routeOf(new URL(request.url).pathname);
    if (!["/fixture-odds", "/health", "/settings", "/board-cache", "/prewarm"].includes(route)) return response({ ok: false, version: VERSION, error: "NOT_FOUND" }, 404);
    return gate(env).fetch(request);
  }

